// FIXTURES //

var Q_NQ_GE_K_LEFT = require( './fixtures/q_nq_ge_k_left.json' );
var Q_NQ_LT_K_LEFT = require( './fixtures/q_nq_lt_k_left.json' );
var Q_NQ_LT_K_RIGHT = require( './fixtures/q_nq_lt_k_right.json' );
